def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    vertical_cols = {
        c for r in range(h) for c in range(w)
        if grid[r][c] == 1 and r in (0, h - 1)
    }
    horizontal_rows = {
        r for r in range(h) for c in range(w)
        if grid[r][c] == 1 and c in (0, w - 1)
    }

    # Lines extend across the grid from each boundary marker.
    line_cells = set()
    for c in vertical_cols:
        line_cells.update((r, c) for r in range(h))
    for r in horizontal_rows:
        line_cells.update((r, c) for c in range(w))

    # Any 2-object touched by, or directly adjacent to, a line is recolored.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            if any((y, x) in line_cells or
                   any((y + dy, x + dx) in line_cells
                       for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)))
                   for y, x in component):
                for y, x in component:
                    out[y][x] = 1

    for r, c in line_cells:
        out[r][c] = 1
    return out
